<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientSubjectTypeVO;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClientSubjectTypeOptions;

trait TrustedClientSubjectTypeAttributeHolder
{
    protected TrustedClientSubjectTypeVO|TrustedClientSubjectTypeOptions|null $subjectType = null;
    protected bool $subjectTypeAssigned = false;

    public function getSubjectTypeOrCurrent(TrustedClientSubjectTypeVO $subjectType): TrustedClientSubjectTypeVO
    {
        if ($this->subjectTypeAssigned) {
            \assert(null !== $this->subjectType);
            return TrustedClientSubjectTypeVO::from($this->subjectType);
        } else {
            return $subjectType;
        }
    }
    public function subjectTypeTryBuildInitial(ConstraintFailList $error): ?TrustedClientSubjectTypeVO
    {
        return  TrustedClientSubjectTypeVO::tryFrom($this->subjectTypeAssigned ? $this->subjectType : TrustedClientSubjectTypeOptions::PUBLIC, $error);
    }
    public function subjectType(TrustedClientSubjectTypeVO|TrustedClientSubjectTypeOptions $subjectType): static
    {
        $this->subjectType = $subjectType;
        $this->subjectTypeAssigned = true;
        return $this;
    }
    public function getSubjectType(): ?TrustedClientSubjectTypeOptions
    {
        return $this->subjectType instanceof TrustedClientSubjectTypeVO ? $this->subjectType->value() : $this->subjectType;
    }
    public function isSubjectTypeAssigned(): bool
    {
        return $this->subjectTypeAssigned;
    }
    public function writeSubjectTypeTo(mixed $att): void
    {
        if ($this->subjectTypeAssigned) {
            \assert(null !== $this->subjectType);
            $att->subjectType($this->subjectType);
        }
    }
    public function readSubjectTypeFrom(mixed $att): void
    {
        if ($att->isSubjectTypeAssigned()) {
            $subjectType = $att->getSubjectType();
            \assert(null !== $subjectType);
            $this->subjectType($subjectType);
        }
    }
    public function unsetSubjectType(): static
    {
        $this->subjectTypeAssigned = false;
        return $this;
    }
    protected function withDefaultSubjectType(): void
    {
        if ($this->subjectType === null) {
            $this->subjectType = TrustedClientSubjectTypeOptions::PUBLIC;
        }
    }
    protected function withAssertedSubjectTypeRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->subjectTypeAssigned = $this->subjectTypeAssigned) {
            $value->subjectType = TrustedClientSubjectTypeVO::tryFrom($this->subjectType, $errorsList);
        }
    }
}
